INSERT INTO "FaqItem" ("id", "question", "answer", "category", "position", "isPublished", "updatedAt") VALUES ('seed-faq-0', 'Can I personalize my order?', 'Yes — products marked “Can be personalized” let you add names, dates or a short message on the product page. For something different, send a [custom request](/custom-order).', 'Ordering', 0, false, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "FaqItem" ("id", "question", "answer", "category", "position", "isPublished", "updatedAt") VALUES ('seed-faq-1', 'Do I need an account to order?', 'No, you can check out as a guest. An account lets you track orders, save addresses and keep a wishlist.', 'Ordering', 1, false, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "FaqItem" ("id", "question", "answer", "category", "position", "isPublished", "updatedAt") VALUES ('seed-faq-2', 'Can I order favors for a wedding, baptism or event?', 'Yes. Send a custom request with the quantity, colors, names and the date you need them. We''ll reply with a quote and timing — nothing is charged until you confirm. [Mention your minimum quantity and lead time.]', 'Ordering', 2, false, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "FaqItem" ("id", "question", "answer", "category", "position", "isPublished", "updatedAt") VALUES ('seed-faq-3', 'How can I pay?', 'The payment options available for your order are shown at checkout. [List your enabled methods, e.g. cash on delivery, Whish Money or bank transfer.] For transfers, your order is confirmed as paid once we verify the payment.', 'Payment', 3, false, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "FaqItem" ("id", "question", "answer", "category", "position", "isPublished", "updatedAt") VALUES ('seed-faq-4', 'I sent a Whish Money or bank transfer. What now?', 'Open your order page from the confirmation email (or your account) and enter the transaction reference. We''ll confirm as soon as we''ve verified the payment.', 'Payment', 4, false, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "FaqItem" ("id", "question", "answer", "category", "position", "isPublished", "updatedAt") VALUES ('seed-faq-5', 'How long will my order take?', 'Each product shows its making time. Delivery usually takes [X–Y] working days after your order is ready. See [Delivery & pickup](/pages/delivery-and-pickup).', 'Delivery', 5, false, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "FaqItem" ("id", "question", "answer", "category", "position", "isPublished", "updatedAt") VALUES ('seed-faq-6', 'Do you deliver outside Lebanon?', '[Answer depending on your business.]', 'Delivery', 6, false, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO "FaqItem" ("id", "question", "answer", "category", "position", "isPublished", "updatedAt") VALUES ('seed-faq-7', 'How should I care for my candle?', '[Add your care instructions — e.g. trim the wick, burn for 2–3 hours the first time, never leave a burning candle unattended, keep away from children and pets.]', 'Care', 7, false, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
